static void require(bool ok,const char *message) {if (!ok) throw std::runtime_error(message);}
static void events() {QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);}
static QByteArray read(const QString &p) {QFile f(p);require(f.open(QIODevice::ReadOnly),"Tank evidence missing");return f.readAll();}
static void write(const QString &p,const QByteArray &b) {QFile f(p);require(f.open(QIODevice::WriteOnly) && f.write(b)==b.size(),"Tank evidence write failed");}
static void reveal(QWidget *control) {
   require(control,"Tank parameter control missing");for (QWidget *page=control;page;page=page->parentWidget()) {for (auto *tabs:control->window()->findChildren<QTabWidget *>()) if (tabs->indexOf(page)>=0) tabs->setCurrentWidget(page);if (auto *scroll=qobject_cast<QScrollArea *>(page)) scroll->ensureWidgetVisible(control);}events();require(control->isVisible() && control->isEnabled(),"Tank parameter control unreachable");
}
static void setField(ResourceEditor *panel,const QString &name,const QString &value) {
   if (auto *line=panel->findChild<QLineEdit *>("resource_"+name)) {reveal(line);line->setText(value);}
   else if (auto *choice=panel->findChild<QComboBox *>("resource_"+name)) {reveal(choice);require(choice->findText(value)>=0,"Tank enumeration choice absent");choice->setCurrentText(value);}
   else throw std::runtime_error("Actual tank resource field missing");events();
}
